(r=>{r("body").on("click",'.westio-login-form-ajax button[type="submit"]',function(e){e.preventDefault();let o=r(this).closest("form");o.length&&r.ajax({type:"POST",url:westioAjax.ajaxurl,data:o.serialize(),beforeSend:function(){o.addClass("loading"),o.find("input, button").prop("disabled",!0),o.find(".result-error").remove()},success:function(e){e.status?location.reload():(e=e.msg||"Login failed. Please try again.",o.prepend(`<div class="result-error woocommerce-message woocommerce-error">${e}</div>`))},error:function(){o.prepend('<div class="result-error woocommerce-message woocommerce-error">Server connection error. Please try again later.</div>')},complete:function(){o.find("input, button").prop("disabled",!1),o.removeClass("loading")}})})})(jQuery);